<template>
  <el-container>
    <el-header width="auto" style="margin-top: 4px">
      <AsideVue/>
    </el-header>

    <el-main class="main-ctx">
      <div class="camera-wrapper">

        <!-- 第一列：实时摄像头画面 -->
        <el-card class="col-card">
          <template #header>
            <div class="card-header-row">
              <el-button type="text" @click="goBack">
                <el-icon><ArrowLeftBold/></el-icon> 返回
              </el-button>
              <el-tag :type="isRunning ? 'success' : 'info'" style="padding: 8px 16px; font-size: 13px">
                {{ isRunning ? '● 实时分析中' : '摄像头未开启' }}
              </el-tag>
            </div>
          </template>

          <!-- 摄像头画面 -->
          <div class="video-container">
            <img v-if="isRunning"
                 :src="feedUrl"
                 class="camera-feed"
                 alt="实时画面"/>
            <div v-else class="camera-placeholder">
              <el-icon :size="64" style="color: #c0ccda"><VideoCamera/></el-icon>
              <div style="margin-top: 16px; color: #909399; font-size: 14px">点击下方按钮开启摄像头</div>
            </div>
          </div>

          <!-- 控制按钮 -->
          <div style="margin-top: 14px; display: flex; gap: 12px">
            <el-button
              v-if="!isRunning"
              type="success"
              size="large"
              style="flex: 1; font-size: 14px"
              @click="startCamera">
              <el-icon style="margin-right: 6px"><VideoPlay/></el-icon>
              开始实时分析
            </el-button>
            <el-button
              v-if="isRunning"
              type="danger"
              size="large"
              style="flex: 1; font-size: 14px"
              @click="stopCamera">
              <el-icon style="margin-right: 6px"><VideoPause/></el-icon>
              停止分析
            </el-button>
          </div>
        </el-card>

        <!-- 第二列：实时统计数据 -->
        <el-card class="col-card">
          <template #header>
            <span style="font-weight: 600; font-size: 15px">实时分析结果</span>
          </template>

          <el-empty v-if="!isRunning && !finalResult" description="开启摄像头后实时展示分析数据" />

          <div v-if="isRunning || finalResult">
            <!-- 当前表情 -->
            <div class="section-title">当前检测状态</div>
            <div class="current-status">
              <div class="face-count-badge">
                <span class="face-num">{{ liveStats.face_count || 0 }}</span>
                <span class="face-label">检测到人脸</span>
              </div>
              <div class="current-emotion-badge" :style="{background: currentEmotionColor}">
                {{ liveStats.current_emotion || '等待检测' }}
              </div>
            </div>

            <el-divider/>

            <!-- 专注度评分 -->
            <div class="section-title">专注度评分</div>
            <div class="score-block">
              <el-progress
                type="dashboard"
                :percentage="liveStats.attention_score || 0"
                :color="scoreColor"
                :stroke-width="14"
                :width="130"
              >
                <template #default>
                  <div class="score-inner">
                    <div class="score-num">{{ liveStats.attention_score || 0 }}</div>
                    <div class="score-unit">分</div>
                  </div>
                </template>
              </el-progress>
              <div class="score-info">
                <div class="score-level" :style="{color: scoreColor}">{{ scoreLevel }}</div>
                <div class="score-comment">{{ scoreComment }}</div>
              </div>
            </div>

            <el-divider/>

            <!-- 表情统计 -->
            <div class="section-title">表情统计（累计）</div>
            <div class="emotion-bars">
              <div class="emotion-bar-item"
                   v-for="(count, emotion) in filteredEmotionCount"
                   :key="emotion">
                <div class="emotion-label">{{ emotion }}</div>
                <el-progress
                  :percentage="getEmotionPercent(count)"
                  :color="emotionColors[emotion]"
                  :stroke-width="16"
                  style="flex: 1"
                />
                <div class="emotion-count">{{ count }}帧</div>
              </div>
            </div>

            <el-divider/>

            <!-- 累计帧数 -->
            <div style="font-size: 13px; color: #909399; text-align: center">
              已分析 {{ liveStats.total_frames || 0 }} 帧
            </div>
          </div>
        </el-card>

        <!-- 第三列：分析报告 -->
        <el-card class="col-card">
          <template #header>
            <span style="font-weight: 600; font-size: 15px">分析报告</span>
          </template>

          <el-empty v-if="!finalResult" description="停止分析后可生成报告" />

          <div v-if="finalResult">
            <div class="section-title">本次分析汇总</div>

            <div class="summary-item">
              <span class="summary-label">总分析帧数</span>
              <span class="summary-value">{{ finalResult.total_frames }} 帧</span>
            </div>
            <div class="summary-item">
              <span class="summary-label">最终专注度</span>
              <span class="summary-value" :style="{color: finalScoreColor}">
                {{ finalResult.attention_score }} 分
              </span>
            </div>
            <div class="summary-item" v-for="(count, emotion) in finalEmotionCount" :key="emotion">
              <span class="summary-label">{{ emotion }}</span>
              <span class="summary-value">{{ count }} 帧</span>
            </div>

            <el-divider/>

            <div style="display: flex; flex-direction: column; gap: 10px; margin-top: 10px">
              <el-button type="success" size="large"
                         :loading="reportLoading"
                         @click="generateReport"
                         style="width: 100%; font-size: 14px">
                <el-icon style="margin-right: 6px"><Document/></el-icon>
                {{ reportLoading ? '正在生成报告...' : '生成分析报告' }}
              </el-button>
              <a v-if="reportUrl" :href="reportUrl" target="_blank" download style="width: 100%">
                <el-button type="primary" plain size="large" style="width: 100%; font-size: 14px">
                  <el-icon style="margin-right: 6px"><Download/></el-icon>
                  下载PDF报告
                </el-button>
              </a>
            </div>
          </div>
        </el-card>

      </div>
    </el-main>
  </el-container>
</template>

<script>
import "@/assets/css/app.css";
import axios from 'axios';
import AsideVue from "@/components/AsideVue";
import { ArrowLeftBold, VideoPlay, VideoPause, VideoCamera, Document, Download } from "@element-plus/icons-vue";

export default {
  name: "CameraAnalysis",
  components: {
    AsideVue,
    ArrowLeftBold,
    VideoPlay,
    VideoPause,
    VideoCamera,
    Document,
    Download,
  },
  data() {
    return {
      isRunning: false,
      feedUrl: '/api/videoFeed',
      statsTimer: null,
      liveStats: {
        emotion_count: { '专注': 0, '开心': 0, '惊讶': 0, '愤怒': 0, '无人脸': 0 },
        total_frames: 0,
        attention_score: 0,
        current_emotion: '',
        face_count: 0,
      },
      finalResult: null,
      reportLoading: false,
      reportUrl: '',
      emotionColors: {
        '专注': '#67C23A',
        '开心': '#409EFF',
        '惊讶': '#E6A23C',
        '愤怒': '#F56C6C',
      },
    };
  },

  computed: {
    scoreColor() {
      const s = this.liveStats.attention_score || 0;
      if (s >= 70) return '#67C23A';
      if (s >= 40) return '#E6A23C';
      return '#F56C6C';
    },
    scoreLevel() {
      const s = this.liveStats.attention_score || 0;
      if (s >= 70) return '优秀';
      if (s >= 40) return '一般';
      return '较低';
    },
    scoreComment() {
      const s = this.liveStats.attention_score || 0;
      if (s >= 70) return '课堂专注度良好，学习状态积极！';
      if (s >= 40) return '专注度中等，可适当引导提升。';
      return '专注度偏低，建议教师加强互动。';
    },
    currentEmotionColor() {
      const colors = {
        '专注': '#67C23A', '开心': '#409EFF',
        '惊讶': '#E6A23C', '愤怒': '#F56C6C', '无人脸': '#909399'
      };
      return colors[this.liveStats.current_emotion] || '#909399';
    },
    filteredEmotionCount() {
      const ec = this.liveStats.emotion_count || {};
      const result = {};
      ['专注', '开心', '惊讶', '愤怒'].forEach(k => {
        if (ec[k] !== undefined) result[k] = ec[k];
      });
      return result;
    },
    finalEmotionCount() {
      if (!this.finalResult) return {};
      const ec = this.finalResult.emotion_count || {};
      const result = {};
      ['专注', '开心', '惊讶', '愤怒'].forEach(k => {
        if (ec[k] !== undefined) result[k] = ec[k];
      });
      return result;
    },
    finalScoreColor() {
      const s = this.finalResult?.attention_score || 0;
      if (s >= 70) return '#67C23A';
      if (s >= 40) return '#E6A23C';
      return '#F56C6C';
    },
  },

  beforeUnmount() {
    this.clearStatsTimer();
    if (this.isRunning) {
      axios.post('/api/stopCamera').catch(() => {});
    }
  },

  methods: {
    goBack() {
      this.$router.go(-1);
    },

    getEmotionPercent(count) {
      const ec = this.liveStats.emotion_count || {};
      const noFace = ec['无人脸'] || 0;
      const faceFrames = (this.liveStats.total_frames || 0) - noFace;
      if (faceFrames === 0) return 0;
      return Math.round((count / faceFrames) * 100);
    },

    async startCamera() {
      try {
        await axios.post('/api/startCamera');
        this.isRunning = true;
        this.finalResult = null;
        this.reportUrl = '';
        this.liveStats = {
          emotion_count: { '专注': 0, '开心': 0, '惊讶': 0, '愤怒': 0, '无人脸': 0 },
          total_frames: 0,
          attention_score: 0,
          current_emotion: '',
          face_count: 0,
        };
        // 每秒拉取一次实时统计
        this.statsTimer = setInterval(this.fetchStats, 1000);
        this.$message.success('摄像头已开启，开始实时分析！');
      } catch (error) {
        this.$message.error('摄像头开启失败，请检查后端服务');
      }
    },

    async stopCamera() {
      this.clearStatsTimer();
      try {
        const response = await axios.post('/api/stopCamera');
        this.finalResult = response.data;
        this.liveStats = { ...this.liveStats, ...response.data };
      } catch (error) {
        console.error('停止摄像头失败', error);
      }
      this.isRunning = false;
      this.$message.success('分析已停止，可生成报告');
    },

    async fetchStats() {
      try {
        const response = await axios.get('/api/cameraStats');
        this.liveStats = response.data;
      } catch (error) {
        console.error('获取统计失败', error);
      }
    },

    clearStatsTimer() {
      if (this.statsTimer) {
        clearInterval(this.statsTimer);
        this.statsTimer = null;
      }
    },

    async generateReport() {
      if (!this.finalResult) {
        this.$message.warning('请先停止分析再生成报告');
        return;
      }
      this.reportLoading = true;
      try {
        const response = await axios.post('/api/generateReport', {
          emotion_count: this.finalResult.emotion_count,
          attention_score: this.finalResult.attention_score,
          total_frames: this.finalResult.total_frames,
          video_name: '实时摄像头分析',
        });
        this.reportUrl = response.data.reportUrl || '';
        this.$message.success('报告生成成功，点击下载！');
      } catch (error) {
        this.$message.error('报告生成失败，请检查后端服务');
      } finally {
        this.reportLoading = false;
      }
    },
  },
};
</script>

